import { useState } from "react";
import { Button, Text, View } from "react-native";

export default function SnapshotCounter() {
  const [count, setCount] = useState(0);
  return (
    <View style={{ padding: 24, gap: 16 }}>
      <Text accessibilityLiveRegion="polite">Count: {count}</Text>
      <Button title="Queue two replacements" onPress={() => {
        setCount(count + 1);
        setCount(count + 1);
      }} />
      <Button title="Queue two updaters" onPress={() => {
        setCount(previous => previous + 1);
        setCount(previous => previous + 1);
      }} />
      <Button title="Reset" onPress={() => setCount(0)} />
    </View>
  );
}

export type Summary = { id: string; nickname: string };
export type Action =
  | { type: "rename"; id: string; nickname: string }
  | { type: "remove"; id: string };

export function summariesReducer(
  state: Summary[], action: Action,
): Summary[] {
  switch (action.type) {
    case "rename":
      return state.map(plant => plant.id === action.id
        ? { ...plant, nickname: action.nickname }
        : plant);
    case "remove":
      return state.filter(plant => plant.id !== action.id);
  }
}

import { useReducer } from "react";
import { Button, Text, View } from "react-native";
import { summariesReducer } from "./plant-summary-reducer";

export default function SummaryEditor() {
  const [plants, dispatch] = useReducer(summariesReducer, [
    { id: "east", nickname: "Lemon" },
    { id: "west", nickname: "Lemon" },
  ]);
  return (
    <View style={{ padding: 24, gap: 16 }}>
      {plants.map(plant => <Text key={plant.id}>
        {plant.id}: {plant.nickname}
      </Text>)}
      <Button title="Rename the east tree" onPress={() => dispatch({
        type: "rename", id: "east", nickname: "Balcony lemon",
      })} />
    </View>
  );
}
